import sys
import threading


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"

    def evaluate_all() -> dict:
        sys.setrecursionlimit(1_000_000)
        values: dict = {}
        visiting: set = set()

        def tokenize(s: str):
            toks = []
            i, n = 0, len(s)
            while i < n:
                c = s[i]
                if c.isspace():
                    i += 1
                elif c.isdigit():
                    j = i
                    while j < n and s[j].isdigit():
                        j += 1
                    toks.append(("num", int(s[i:j])))
                    i = j
                elif "A" <= c <= "Z":
                    j = i
                    while j < n and "A" <= s[j] <= "Z":
                        j += 1
                    word = s[i:j]
                    if len(word) == 1 and j < n and s[j].isdigit():
                        k = j
                        while k < n and s[k].isdigit():
                            k += 1
                        toks.append(("cell", word + s[j:k]))
                        i = k
                    else:
                        toks.append(("name", word))
                        i = j
                elif c == "<":
                    if i + 1 < n and s[i + 1] == "=":
                        toks.append(("<=", None))
                        i += 2
                    elif i + 1 < n and s[i + 1] == ">":
                        toks.append(("<>", None))
                        i += 2
                    else:
                        toks.append(("<", None))
                        i += 1
                elif c == ">":
                    if i + 1 < n and s[i + 1] == "=":
                        toks.append((">=", None))
                        i += 2
                    else:
                        toks.append((">", None))
                        i += 1
                elif c == "=":
                    toks.append(("=", None))
                    i += 1
                elif c in "+-*/(),:":
                    toks.append((c, None))
                    i += 1
                else:
                    i += 1
            toks.append(("eof", None))
            return toks

        def parse(text: str):
            toks = tokenize(text)
            pos = [0]

            def peek():
                return toks[pos[0]]

            def advance():
                tok = toks[pos[0]]
                pos[0] += 1
                return tok

            def expect(kind):
                return advance()

            def parse_expr():
                node = parse_term()
                while peek()[0] in ("+", "-"):
                    op = advance()[0]
                    node = ("bin", op, node, parse_term())
                return node

            def parse_term():
                node = parse_factor()
                while peek()[0] in ("*", "/"):
                    op = advance()[0]
                    node = ("bin", op, node, parse_factor())
                return node

            def parse_factor():
                neg = False
                while peek()[0] == "-":
                    advance()
                    neg = not neg
                node = parse_atom()
                return ("neg", node) if neg else node

            def parse_atom():
                kind, val = advance()
                if kind == "num":
                    return ("num", val)
                if kind == "cell":
                    return ("cell", val)
                if kind == "(":
                    node = parse_expr()
                    expect(")")
                    return node
                if kind == "name":
                    expect("(")
                    if val == "IF":
                        left = parse_expr()
                        op = advance()[0]
                        right = parse_expr()
                        expect(",")
                        then = parse_expr()
                        expect(",")
                        els = parse_expr()
                        expect(")")
                        return ("if", left, op, right, then, els)
                    args = []
                    while True:
                        if (
                            peek()[0] == "cell"
                            and pos[0] + 1 < len(toks)
                            and toks[pos[0] + 1][0] == ":"
                        ):
                            c1 = advance()[1]
                            expect(":")
                            c2 = expect("cell")[1]
                            args.append(("range", c1, c2))
                        else:
                            args.append(("expr", parse_expr()))
                        if peek()[0] == ",":
                            advance()
                        else:
                            expect(")")
                            break
                    return ("call", val, args)
                raise ValueError("unexpected token")

            return parse_expr()

        def compare(l, op, r):
            if op == "=":
                return l == r
            if op == "<>":
                return l != r
            if op == "<":
                return l < r
            if op == "<=":
                return l <= r
            if op == ">":
                return l > r
            return l >= r

        def range_names(a, b):
            c1, r1 = ord(a[0]) - 65, int(a[1:])
            c2, r2 = ord(b[0]) - 65, int(b[1:])
            if c1 > c2:
                c1, c2 = c2, c1
            if r1 > r2:
                r1, r2 = r2, r1
            for r in range(r1, r2 + 1):
                for c in range(c1, c2 + 1):
                    yield chr(65 + c) + str(r)

        def is_err(v):
            return isinstance(v, str)

        def ev(node):
            kind = node[0]
            if kind == "num":
                return node[1]
            if kind == "cell":
                return cell_value(node[1])
            if kind == "neg":
                v = ev(node[1])
                return v if is_err(v) else -v
            if kind == "bin":
                _, op, l, r = node
                lv = ev(l)
                if is_err(lv):
                    return lv
                rv = ev(r)
                if is_err(rv):
                    return rv
                if op == "+":
                    return lv + rv
                if op == "-":
                    return lv - rv
                if op == "*":
                    return lv * rv
                if rv == 0:
                    return DIV0
                q = abs(lv) // abs(rv)
                return -q if (lv < 0) != (rv < 0) else q
            if kind == "if":
                lv = ev(node[1])
                if is_err(lv):
                    return lv
                rv = ev(node[3])
                if is_err(rv):
                    return rv
                return ev(node[4] if compare(lv, node[2], rv) else node[5])
            _, fname, args = node
            if fname == "SUM":
                total = 0
                for arg in args:
                    if arg[0] == "range":
                        for nm in range_names(arg[1], arg[2]):
                            if nm in cells:
                                v = cell_value(nm)
                                if is_err(v):
                                    return v
                                total += v
                    else:
                        v = ev(arg[1])
                        if is_err(v):
                            return v
                        total += v
                return total
            best = None
            for arg in args:
                if arg[0] == "range":
                    for nm in range_names(arg[1], arg[2]):
                        if nm not in cells:
                            continue
                        v = cell_value(nm)
                        if is_err(v):
                            return v
                        if best is None or (fname == "MIN" and v < best) or (
                            fname == "MAX" and v > best
                        ):
                            best = v
                else:
                    v = ev(arg[1])
                    if is_err(v):
                        return v
                    if best is None or (fname == "MIN" and v < best) or (
                        fname == "MAX" and v > best
                    ):
                        best = v
            return 0 if best is None else best

        def cell_value(name):
            if name in values:
                return values[name]
            if name not in cells:
                return 0
            if name in visiting:
                return CYCLE
            visiting.add(name)
            try:
                content = cells[name].strip()
                if content.startswith("="):
                    v = ev(parse(content[1:]))
                else:
                    v = int(content)
            finally:
                visiting.discard(name)
            values[name] = v
            return v

        for name in cells:
            cell_value(name)
        return {name: values[name] for name in cells}

    outcome = []

    def work():
        try:
            outcome.append(("ok", evaluate_all()))
        except BaseException as exc:
            outcome.append(("err", exc))

    old_size = None
    try:
        old_size = threading.stack_size()
        threading.stack_size(256 * 1024 * 1024)
    except (ValueError, RuntimeError, OSError):
        pass
    t = threading.Thread(target=work)
    t.start()
    t.join()
    if old_size is not None:
        try:
            threading.stack_size(old_size)
        except (ValueError, RuntimeError, OSError):
            pass

    kind, payload = outcome[0]
    if kind == "err":
        raise payload
    return payload
